package de.elbracht.smp.agent;
import com.fasterxml.jackson.databind.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.zip.*;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/** Complete owned sets and explicitly hash-matched imports; never drops unmapped manual JARs. */
@Service @EnableConfigurationProperties(ModControlProperties.class)
public class ModPlanService {
 public record Root(long projectId,long fileId){}
 public record Pin(long projectId,long fileId,long bytes,String sha256,String sha1,List<Long> required,String provenance){public String name(){return "cf-"+projectId+"-"+fileId+".jar";}}
 public record Package(Pin pin,String content){}
 public record Manifest(int schema,List<Root> roots,List<Pin> files){}
 public record State(boolean managed,String revision,Manifest manifest,Map<String,String> actualFiles,String reasonCode){}
 public record Request(String minecraftVersion,String loaderVersion,String javaVersion,String revision,List<Root> roots,List<Package> packages,Map<String,Long> imports){public Request(String minecraftVersion,String loaderVersion,String javaVersion,String revision,List<Root> roots,List<Package> packages){this(minecraftVersion,loaderVersion,javaVersion,revision,roots,packages,Map.of());}}
 public record Plan(UUID planId,String createdAt,String expiresAt,String minecraftVersion,String loaderVersion,String javaVersion,List<Pin> files,List<String> changes,String state){}
 private final ModControlProperties properties;private final LocalBackupService backups;private final DockerControl control;private final ContainerProbe docker;private final MinecraftProbe minecraft;private final RconPlayerReader rcon;private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final AtomicBoolean faultUsed=new AtomicBoolean();
 public ModPlanService(ModControlProperties properties,AgentProperties agent,LocalBackupService backups,DockerControl control,ContainerProbe docker,MinecraftProbe minecraft,RconPlayerReader rcon,JdbcTemplate jdbc,ObjectMapper mapper){this.properties=properties;this.backups=backups;this.control=control;this.docker=docker;this.minecraft=minecraft;this.rcon=rcon;this.jdbc=jdbc;this.mapper=mapper.copy().enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).enable(com.fasterxml.jackson.core.JsonParser.Feature.STRICT_DUPLICATE_DETECTION);if(properties.enabled()&&(!"docker-test-control".equals(agent.mode())||!backups.bootTestsAvailable()||!rcon.available()))throw new IllegalStateException("Modsteuerung benötigt vollständigen isolierten Backup-/Probeanschluss");}
 public boolean available(){return properties.enabled();}
 public State state()throws Exception{
  if(!available())throw new OperationRejected(503,"TEST_MODS_DISABLED");var hashes=control.readTestModHashes();byte[] raw=control.readTestModManifest();String revision=revision(hashes,raw);Manifest manifest=new Manifest(1,List.of(),List.of());
  if(raw.length==0)return new State(hashes.isEmpty(),revision,manifest,hashes,hashes.isEmpty()?null:"MANUAL_MODS_REQUIRE_IMPORT");
  try{manifest=mapper.readValue(raw,Manifest.class);validateManifest(manifest);if(!hashes.equals(hashes(manifest)))throw new IOException();return new State(true,revision,manifest,hashes,null);}catch(Exception error){return new State(false,revision,new Manifest(1,List.of(),List.of()),hashes,"MOD_MANIFEST_NOT_VERIFIED");}
 }
 public synchronized Plan create(Request request)throws Exception{
  if(!available())throw new OperationRejected(503,"TEST_MODS_DISABLED");if(request==null||request.packages()==null||request.roots()==null||request.packages().size()>32||request.revision()==null||!request.revision().matches("[a-f0-9]{64}"))throw new OperationRejected(422,"INVALID_MOD_PLAN");
  var before=state();boolean importing=request.imports()!=null&&!request.imports().isEmpty();if(!before.revision().equals(request.revision())||!importing&&!before.managed()||importing&&(before.managed()||!"MANUAL_MODS_REQUIRE_IMPORT".equals(before.reasonCode())))throw new OperationRejected(409,"MOD_INVENTORY_CHANGED_OR_UNMAPPED");
  var running=docker.inspect();var profile=control.readTestRuntimeProfile();String java=control.readTestJavaVersion();
  if(!running.targetMatches()||!running.running()||profile==null||!"26.3".equals(request.minecraftVersion())||!request.minecraftVersion().equals(profile.minecraftVersion())||!"0.19.5".equals(request.loaderVersion())||!request.loaderVersion().equals(profile.loaderVersion())||!java.equals(request.javaVersion()))throw new OperationRejected(409,"MOD_RUNTIME_CHANGED");
  if(jdbc.queryForObject("SELECT COUNT(*) FROM mod_plan WHERE state='PLANNED' AND expires_at>?",Integer.class,Instant.now().toString())>=2)throw new OperationRejected(409,"MOD_PLAN_LIMIT");
  var manifest=new Manifest(1,List.copyOf(request.roots()),request.packages().stream().map(Package::pin).toList());validateManifest(manifest);if(importing)validateImport(before,request.imports(),manifest);long total=0;UUID id=UUID.randomUUID();Path directory=backups.newModPlanDirectory(id);boolean recorded=false;
  try{
   for(var pack:request.packages()){var pin=pack.pin();if(pack.content()==null||pack.content().length()>11184812)throw new IOException("MOD_PACKAGE_LIMIT");byte[] bytes=Base64.getDecoder().decode(pack.content());total+=bytes.length;if(bytes.length!=pin.bytes()||total>8L*1024*1024||!hash("SHA-256",bytes).equals(pin.sha256())||!hash("SHA-1",bytes).equals(pin.sha1()))throw new IOException("MOD_PACKAGE_NOT_VERIFIED");verifyJar(bytes);Files.write(directory.resolve(pin.name()),bytes,StandardOpenOption.CREATE_NEW);}
   Files.write(directory.resolve("portal-mod-manifest.json"),mapper.writeValueAsBytes(manifest),StandardOpenOption.CREATE_NEW);List<String> changes=new ArrayList<>();if(importing)changes.add("Import: Alle vorhandenen JAR-Dateien anhand bestätigter Hashes in das Portal-Manifest übernehmen");var old=before.actualFiles();var next=hashes(manifest);for(String name:old.keySet())if(!next.containsKey(name))changes.add("Entfernen: "+name);for(var entry:next.entrySet())if(!entry.getValue().equals(old.get(entry.getKey())))changes.add((old.containsKey(entry.getKey())?"Ersetzen: ":"Hinzufügen: ")+entry.getKey());if(changes.isEmpty()&&!new HashSet<>(before.manifest().roots()).equals(new HashSet<>(manifest.roots())))changes.add("Mod-Auswahl im Manifest aktualisieren; benötigte Abhängigkeiten bleiben erhalten");if(changes.isEmpty())throw new OperationRejected(409,"MOD_PLAN_NO_CHANGES");
   Instant now=Instant.now();jdbc.update("INSERT INTO mod_plan(id,created_at,expires_at,target_identity,mod_revision,stage_digest,manifest_json,changes_json,java_version,import_verified,state) VALUES(?,?,?,?,?,?,?,?,?,?,'PLANNED')",id,now.toString(),now.plusSeconds(900).toString(),control.testTargetIdentity(),before.revision(),RestoreService.digest(directory),mapper.writeValueAsString(manifest),mapper.writeValueAsString(changes),java,importing);recorded=true;return find(id);
  }finally{if(!recorded)backups.discardModPlanDirectory(id);}
 }
 public Plan find(UUID id){return jdbc.query("SELECT * FROM mod_plan WHERE id=?",(rs,n)->{try{return new Plan(id,rs.getString("created_at"),rs.getString("expires_at"),"26.3","0.19.5",rs.getString("java_version"),mapper.readValue(rs.getString("manifest_json"),Manifest.class).files(),mapper.readValue(rs.getString("changes_json"),mapper.getTypeFactory().constructCollectionType(List.class,String.class)),rs.getString("state"));}catch(Exception error){throw new IllegalStateException();}},id).stream().findFirst().orElseThrow(()->new OperationRejected(404,"MOD_PLAN_NOT_FOUND"));}
 public synchronized Plan cancel(UUID id){var plan=find(id);if(plan.state().equals("CANCELLED"))return plan;if(jdbc.update("UPDATE mod_plan SET state='CANCELLED' WHERE id=? AND state='PLANNED'",id)!=1)throw new OperationRejected(409,"MOD_PLAN_NOT_CANCELLABLE");return find(id);}
 public synchronized RestoreService.Outcome apply(UUID id,UUID operation)throws Exception{
  if(!available())throw new OperationRejected(503,"TEST_MODS_DISABLED");var plan=find(id);var row=jdbc.queryForMap("SELECT * FROM mod_plan WHERE id=?",id);final Path packages;
  try{packages=backups.modPlanDirectory(id);var current=state();boolean importing=Boolean.TRUE.equals(row.get("IMPORT_VERIFIED"));if(!plan.state().equals("PLANNED")||!Instant.parse(plan.expiresAt()).isAfter(Instant.now())||!control.testTargetIdentity().equals(row.get("TARGET_IDENTITY"))||!RestoreService.digest(packages).equals(row.get("STAGE_DIGEST"))||!current.managed()&&!(importing&&"MANUAL_MODS_REQUIRE_IMPORT".equals(current.reasonCode()))||!current.revision().equals(row.get("MOD_REVISION"))||!plan.javaVersion().equals(control.readTestJavaVersion()))throw new IOException();}catch(Exception error){throw new OperationRejected(409,"MOD_PLAN_CHANGED");}
  var before=docker.inspect();if(!before.targetMatches()||!before.running()||before.paused()||before.restarting()||before.dead())throw new OperationRejected(409,"MOD_SERVER_NOT_READY");
  DockerControl.DataSwap swap=null;boolean originalIntact=true;jdbc.update("UPDATE mod_plan SET state='APPLYING',operation_id=? WHERE id=?",operation,id);
  try{
   String pre=backups.createBeforeRestore(operation);jdbc.update("UPDATE mod_plan SET pre_backup=? WHERE id=?",pre,id);Path stage=backups.stoppedModStage(operation);if(!stageRevision(stage).equals(row.get("MOD_REVISION")))throw new IOException("MOD_INVENTORY_CHANGED");
   Path mods=stage.resolve("mods");if(!Files.exists(mods))Files.createDirectory(mods);if(!mods.toRealPath().getParent().equals(stage.toRealPath()))throw new IOException();try(var files=Files.list(mods)){for(Path file:files.toList())if(file.getFileName().toString().endsWith(".jar")){if(!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS))throw new IOException();Files.delete(file);}}
   for(var pin:plan.files())Files.copy(packages.resolve(pin.name()),mods.resolve(pin.name()));Files.copy(packages.resolve("portal-mod-manifest.json"),stage.resolve("portal-mod-manifest.json"),StandardCopyOption.REPLACE_EXISTING);backups.verifyModStage(stage,operation);
   swap=control.swapTestData(stage,operation);originalIntact=false;jdbc.update("UPDATE mod_plan SET swap_json=? WHERE id=?",mapper.writeValueAsString(swap),id);if(properties.fault().equals("after-swap")&&faultUsed.compareAndSet(false,true))throw new IOException("Expliziter lokaler Modtestfehler");control.start();ready();if(!state().managed()||!hashes(new Manifest(1,List.of(),plan.files())).equals(control.readTestModHashes()))throw new IOException();
   jdbc.update("UPDATE mod_plan SET state='SUCCEEDED' WHERE id=?",id);return new RestoreService.Outcome("SUCCEEDED","Geprüften Modsatz eingesetzt. Vorabsicherung, isolierter Weltstart ohne Netz, Minecraft-Readiness, RCON und Manifest bestätigt. Vorherige vollständige Daten bleiben als Rückweg erhalten.");
  }catch(Exception failure){
   if(failure instanceof InterruptedException)Thread.currentThread().interrupt();if(failure instanceof DockerControl.DataSwapFailure data)originalIntact=data.originalRestored;
   try{if(swap!=null){if(docker.inspect().running())control.stop();control.rollbackTestData(swap);originalIntact=true;}if(!originalIntact)throw new IOException();if(!docker.inspect().running())control.start();ready();if(!state().revision().equals(row.get("MOD_REVISION")))throw new IOException();jdbc.update("UPDATE mod_plan SET state='ROLLED_BACK' WHERE id=?",id);return new RestoreService.Outcome("FAILED","Modänderung fehlgeschlagen. Vorherige Welt, Moddateien, Manifest und Betriebszustand wiederhergestellt und geprüft. Keine automatische Wiederholung.");}
   catch(Exception rollback){jdbc.update("UPDATE mod_plan SET state='UNKNOWN' WHERE id=?",id);return new RestoreService.Outcome("UNKNOWN","Modänderung oder Rückweg nicht vollständig bestätigt. Datenkopien bleiben erhalten; weitere Mutationen sind gesperrt.");}
  }
 }
 @org.springframework.scheduling.annotation.Scheduled(fixedDelay=60000,initialDelay=60000)
 public synchronized void cleanup(){if(!available())return;Instant now=Instant.now();var ids=jdbc.query("SELECT id FROM mod_plan WHERE stage_cleaned=FALSE AND (state='CANCELLED' OR (state='PLANNED' AND expires_at<?) OR (state IN ('SUCCEEDED','ROLLED_BACK') AND created_at<?)) LIMIT 10",(rs,n)->rs.getObject(1,UUID.class),now.toString(),now.minusSeconds(7*86400).toString());for(UUID id:ids)try{backups.discardModPlanDirectory(id);jdbc.update("UPDATE mod_plan SET stage_cleaned=TRUE,state=CASE WHEN state='PLANNED' THEN 'EXPIRED' ELSE state END WHERE id=?",id);}catch(IOException ignored){}}
 private void validateManifest(Manifest manifest)throws IOException{
  if(manifest==null||manifest.schema()!=1||manifest.files()==null||manifest.roots()==null||manifest.files().size()>32||manifest.roots().size()>32)throw new IOException("INVALID_MOD_MANIFEST");Set<Long> ids=new HashSet<>(),roots=new HashSet<>();long total=0;
  for(var pin:manifest.files()){if(pin==null||pin.projectId()<=0||pin.fileId()<=0||pin.bytes()<1||pin.bytes()>8L*1024*1024||pin.sha256()==null||!pin.sha256().matches("[a-f0-9]{64}")||pin.sha1()==null||!pin.sha1().matches("[a-f0-9]{40}")||pin.required()==null||pin.required().size()>100||!ids.add(pin.projectId())||!("CURSEFORGE".equals(pin.provenance())||properties.fixturesEnabled()&&"LOCAL_ACCEPTANCE_FIXTURE".equals(pin.provenance())))throw new IOException("INVALID_MOD_PIN");total+=pin.bytes();}if(total>8L*1024*1024)throw new IOException("MOD_PACKAGE_LIMIT");
  for(var pin:manifest.files())if(pin.required().stream().anyMatch(id->id==null||!ids.contains(id)))throw new IOException("MOD_DEPENDENCY_MISSING");for(var root:manifest.roots())if(root==null||!roots.add(root.projectId())||manifest.files().stream().noneMatch(file->file.projectId()==root.projectId()&&file.fileId()==root.fileId()))throw new IOException("MOD_ROOT_MISSING");
  Set<Long> reachable=new HashSet<>();Deque<Long> pending=new ArrayDeque<>(roots);while(!pending.isEmpty()){long id=pending.removeFirst();if(!reachable.add(id))continue;for(var pin:manifest.files())if(pin.projectId()==id)pending.addAll(pin.required());}if(!reachable.equals(ids))throw new IOException("MOD_FILE_NOT_REQUIRED_BY_ROOT");
 }
 private static void validateImport(State current,Map<String,Long> imports,Manifest manifest)throws IOException{
  if(imports.isEmpty()||imports.size()>32||!imports.keySet().equals(current.actualFiles().keySet())||new HashSet<>(imports.values()).size()!=imports.size())throw new IOException("MOD_IMPORT_INCOMPLETE");
  for(var entry:imports.entrySet()){if(entry.getKey()==null||!entry.getKey().matches("[A-Za-z0-9_.+ -]{1,180}\\.jar")||entry.getValue()==null||entry.getValue()<=0)throw new IOException("INVALID_MOD_IMPORT");var pin=manifest.files().stream().filter(file->file.projectId()==entry.getValue()).findFirst().orElseThrow(()->new IOException("MOD_IMPORT_PIN_MISSING"));if(!pin.sha256().equals(current.actualFiles().get(entry.getKey()))||manifest.roots().stream().noneMatch(root->root.projectId()==pin.projectId()))throw new IOException("MOD_IMPORT_HASH_MISMATCH");}
 }
 private void verifyJar(byte[] bytes)throws Exception{
  Set<String> names=new HashSet<>();byte[] metadata=null;long expanded=0;try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName();if(names.size()>=20000||name.length()>512||name.startsWith("/")||name.contains("\\")||name.contains(":")||Arrays.stream(name.split("/")).anyMatch(part->part.equals("..")||part.equals("."))||!names.add(name))throw new IOException("UNSAFE_MOD_JAR");var data=name.equals("fabric.mod.json")?new ByteArrayOutputStream():null;byte[] buffer=new byte[8192];int count;while((count=zip.read(buffer))!=-1){expanded+=count;if(expanded>64L*1024*1024||data!=null&&data.size()+count>262144)throw new IOException("MOD_JAR_LIMIT");if(data!=null)data.write(buffer,0,count);}if(data!=null)metadata=data.toByteArray();}}
  if(metadata==null)throw new IOException("FABRIC_METADATA_MISSING");var mod=mapper.readTree(metadata);var env=mod.path("environment");boolean server=env.isMissingNode()||env.isTextual()&&Set.of("*","server").contains(env.asText());if(!mod.path("schemaVersion").isInt()||mod.path("schemaVersion").asInt()!=1||!mod.path("id").asText().matches("[a-z][a-z0-9_-]{1,63}")||mod.path("version").asText().isBlank()||mod.path("version").asText().length()>128||!server)throw new IOException("SERVER_MOD_NOT_CONFIRMED");
 }
 private void ready()throws Exception{long end=System.nanoTime()+Duration.ofSeconds(90).toNanos();while(System.nanoTime()<end){try{var state=docker.inspect();var profile=control.readTestRuntimeProfile();if(state.targetMatches()&&state.running()&&!state.paused()&&!state.restarting()&&!state.dead()&&state.portMatches()&&"26.3".equals(minecraft.query().minecraftVersion())&&profile!=null&&"0.19.5".equals(profile.loaderVersion())){rcon.readOnlineNames();return;}}catch(IOException ignored){}Thread.sleep(500);}throw new IOException("MOD_READINESS_NOT_CONFIRMED");}
 private static Map<String,String> hashes(Manifest manifest){Map<String,String> result=new TreeMap<>();for(var file:manifest.files())result.put(file.name(),file.sha256());return Map.copyOf(result);}
 static String revision(Map<String,String> hashes,byte[] manifest)throws Exception{var digest=MessageDigest.getInstance("SHA-256");for(var entry:new TreeMap<>(hashes).entrySet()){digest.update(entry.getKey().getBytes(StandardCharsets.UTF_8));digest.update((byte)0);digest.update(entry.getValue().getBytes(StandardCharsets.US_ASCII));digest.update((byte)0);}digest.update(manifest);return HexFormat.of().formatHex(digest.digest());}
 private static String stageRevision(Path root)throws Exception{Path mods=root.resolve("mods");Map<String,String> hashes=new TreeMap<>();if(Files.exists(mods))try(var files=Files.list(mods)){for(Path file:files.toList())if(file.getFileName().toString().endsWith(".jar")){if(!Files.isRegularFile(file,LinkOption.NOFOLLOW_LINKS)||Files.size(file)>8L*1024*1024||hashes.size()>=32)throw new IOException();hashes.put(file.getFileName().toString(),hash("SHA-256",Files.readAllBytes(file)));}}Path manifest=root.resolve("portal-mod-manifest.json");if(Files.exists(manifest)&&Files.size(manifest)>262144)throw new IOException();return revision(hashes,Files.exists(manifest)?Files.readAllBytes(manifest):new byte[0]);}
 private static String hash(String algorithm,byte[] bytes)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance(algorithm).digest(bytes));}
}
